TOKEN* tokenize(char* file) {
    TOKEN* head = mktoken();
    TOKEN* lastitem = head;
    TOKEN* curitem = head;
    STRING* tmptoken = mkstring(200);
    CHARTYPE lasttype = space;
    CHARTYPE curtype;
    int lnscount = 1;
    FILE* input = fopen(file, "r");
    unsigned char c;
    while(!feof(input)) {
        c = fgetc(input);
        if(c == '\n')
            lnscount++;
        else if(c == '/' && handlecomment(input, &lnscount)) 
            continue;
        else if(c == '"') {
            if(lasttype != space)
                curitem = appendtoken(curitem, tmptoken, file, lnscount);
            readstr(input, tmptoken, lnscount);
            lastitem = curitem;
            curitem = appendtokenraw(curitem, tmptoken, lnscount, string);
            lasttype = space;
            continue;
        }
        curtype = getchartype(c);
        if(curtype == common) {
            if(lasttype == charsymbol) {
                lastitem = curitem;
                curitem = appendtoken(curitem, tmptoken, file, lnscount);
            }
            append(tmptoken, c);
        } else {
            if(lasttype != space){
                lastitem = curitem;
                curitem = appendtoken(curitem, tmptoken, file, lnscount);
            }
            if(curtype == charsymbol)
                append(tmptoken, c);
        }
        lasttype = curtype;
    }
    if(curitem == head) {
        eprintf("File '%s' is empty\n", file);
        exit(1);
    }
    lastitem->next = NULL;
    free(curitem);
    freestr(tmptoken);
    fclose(input);
    return head;
}

